package com.lostf1sh.pixelplayeross.data.rhythm

import java.io.File
import kotlin.math.abs
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.double
import kotlinx.serialization.json.int
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Compares the Kotlin pipeline against the PC reference implementation on the same audio.
 *
 * The fixture is generated by `gen_dsp_fixture.py`, which runs
 * `RhythmChartLab/rhythm-lab/fourier/fourier_chartgen.py` over a synthetic 120 BPM loop.
 *
 * Matching is deliberately tolerant:
 * - Python `round` is half-to-even, Kotlin `roundToInt` is half-up, so a cell boundary can
 *   land one grid step apart (≈ 250 ms at Easy) with no actual quality difference;
 * - float32/float64 accumulation differs across the two runtimes.
 *
 * A 15 ms two-way match rate above 95% still catches any real divergence (a wrong band
 * layout, a wrong peak threshold or a wrong phase would collapse it immediately).
 */
class RhythmChartGeneratorGoldenTest {

    private val toleranceMs = 15
    private val minimumMatchRate = 0.95

    private fun resource(name: String): File {
        val url = requireNotNull(javaClass.classLoader?.getResource("rhythm/$name")) {
            "missing test resource rhythm/$name — run gen_dsp_fixture.py"
        }
        return File(url.toURI())
    }

    @Test
    fun matchesReferenceImplementationOnFixture() {
        val (audio, sampleRate) = RhythmTestAudio.readMonoWav16(resource("dsp-beats-120bpm.wav"))
        val root = Json.parseToJsonElement(resource("dsp-beats-120bpm.expected.json").readText())
            .jsonObject
        val expectedBpm = root.getValue("bpm").jsonPrimitive.double
        val expectedOffset = root.getValue("offsetMs").jsonPrimitive.double
        val durationMs = root.getValue("durationMs").jsonPrimitive.int
        val difficulties = root.getValue("difficulties").jsonObject

        for (difficulty in DspDifficulty.entries) {
            val block = difficulties.getValue(difficulty.name).jsonObject
            val expectedNotes = block.getValue("notes").jsonArray.map {
                val note = it.jsonObject
                note.getValue("t").jsonPrimitive.double to note.getValue("lane").jsonPrimitive.int
            }
            val expectedTimes = expectedNotes.map { it.first }.sorted()

            // BAND_ORDER: the reference lane mapping, so lanes are comparable too.
            val result = RhythmChartGenerator.generate(
                pcmMono = audio,
                sampleRate = sampleRate,
                durationMs = durationMs,
                params = RhythmChartGenParams(
                    difficulty = difficulty,
                    laneStrategy = LaneStrategy.BAND_ORDER,
                ),
            )
            val chart = result.chart
            val actualTimes = chart.notes.map { it.timeMs.toDouble() }

            val detail = buildString {
                append("${difficulty.name}: bpm ${result.diagnostics.usedBpm} ")
                append("(expected $expectedBpm, offset $expectedOffset) ")
                append("notes ${chart.noteCount()} vs ${expectedTimes.size}")
            }

            assertEquals("$detail — bpm drifted", expectedBpm, result.diagnostics.usedBpm, 0.5)

            val sizeRatio = chart.noteCount().toDouble() / expectedTimes.size
            assertTrue("$detail — note count off by ${(sizeRatio - 1) * 100}%", abs(1 - sizeRatio) <= 0.05)

            val forward = matchRate(actualTimes, expectedTimes, toleranceMs)
            val backward = matchRate(expectedTimes, actualTimes, toleranceMs)
            assertTrue(
                "$detail — match forward=${forward * 100}% backward=${backward * 100}%",
                forward >= minimumMatchRate && backward >= minimumMatchRate,
            )

            // Lanes are intentionally NOT asserted equal. `argmax` over whitened bands is
            // genuinely ambiguous when several bands peak on the same frame (a kick and a
            // hi-hat landing in one quantization cell), so the reference implementation
            // itself flips lanes between neighbouring notes. Reported for diagnosis only.
            val laneAgreement = chart.notes.count { note ->
                expectedNotes.any { (time, lane) ->
                    abs(time - note.timeMs) <= toleranceMs && lane == note.lane
                }
            }
            println(
                "GOLDEN ${difficulty.name}: notes=${chart.noteCount()}/${expectedTimes.size} " +
                    "bpm=${result.diagnostics.usedBpm} " +
                    "forward=${forward * 100}% backward=${backward * 100}% " +
                    "lane=$laneAgreement/${chart.noteCount()}",
            )

            // Only Hard is unambiguous: at 1/4-beat resolution each onset gets its own cell,
            // so the lane follows one deterministic dominant band and must match the reference
            // exactly. At coarser grids a kick and a hi-hat can land in the same cell and
            // `argmax` over whitened bands is genuinely tie-prone, in the reference too.
            if (difficulty == DspDifficulty.HARD) {
                assertTrue(
                    "$detail — hard lane agreement $laneAgreement/${chart.noteCount()}",
                    laneAgreement >= chart.noteCount() * 0.95,
                )
            }
        }
    }

    @Test
    fun fixtureIsAtLeastTwentySecondsOfAudio() {
        val (audio, sampleRate) = RhythmTestAudio.readMonoWav16(resource("dsp-beats-120bpm.wav"))
        assertTrue(audio.size / sampleRate >= 19)
        assertTrue(audio.all { abs(it) <= 1f })
    }

    private fun matchRate(actual: List<Double>, expected: List<Double>, tolerance: Int): Double {
        if (actual.isEmpty() || expected.isEmpty()) return 0.0
        var matched = 0
        for (value in actual) {
            if (expected.any { abs(it - value) <= tolerance }) matched++
        }
        return matched.toDouble() / actual.size
    }
}
